local Vendor = require "ejoysdk_lua.vendors.vendor"
local VENDOR_NAME = 'TRAVLETPAY'
local EM = require "ejoysdk_lua.ejoysdk_module"
local TRAVLETPAY = Vendor:Inherit(VENDOR_NAME)

local _TAG = EM.MODULE.VENDORS.TRAVLET_PAY

local default_shop_url = 'https://shop.vntth.com/sgz2017vn/vn'

function TRAVLETPAY.init()

end

function TRAVLETPAY.pay(_product_id, _count, _order_id, _ext_info,cb)
    local E = require 'ejoysdk_lua.ejoysdk'
    local GP = require 'ejoysdk_lua.ejoysdk_gangplank'
    local EGC = require 'ejoysdk_lua.ejoysdk_gangplank_config'

    local gangplank_config = EGC.get_current_cdn_config()
    local url = gangplank_config['shop_center'] or default_shop_url

    local player_info = GP.player_info() or {}
    local player_id = player_info.player_id

    if not player_id or not _product_id then
        cb(false)
    else
        url = E.Utils.url_append_params(url,'productId',_product_id)
        url = E.Utils.url_append_params(url,'playerId',player_id)
        E.Sysinfo.open_url(url)
        cb(true)
    end

end

function TRAVLETPAY.skip_official_order()
    -- 是否需要海外支付下单
    return true
end

function TRAVLETPAY.skip_gp_order()
    -- 是否需要gangplank下单
    return true
end

return TRAVLETPAY